from pathlib import Path
base=Path('research/labour-force-survey-uncertainty-measurement');src=(base/'scripts/verify_browser.js').read_text(encoding='utf-8')
src=src.replace("const report={errors,failed,mathjaxRendered:","const report={errors,failed,enhancementChecks,mathjaxRendered:")
insert=r'''
const enhancementChecks={stages:[],geographies:[],layouts:[],playback:[]};
assert.equal(await ev("document.querySelectorAll('#journey-steps button').length"),7);
assert.equal(await ev("Object.keys(LFS_MAP).length"),13);
const duplicate=await ev("[...document.querySelectorAll('[id]')].map(e=>e.id).filter((id,i,a)=>a.indexOf(id)!==i)");assert.deepEqual(duplicate,[]);
const links=await ev("[...document.querySelectorAll('a[href^=\"#\"]')].map(a=>a.getAttribute('href').slice(1)).filter(id=>!document.getElementById(id))");assert.deepEqual(links,[]);
for(const code of ['BC','AB','SK','MB','ON','QC','NB','NS','PE','NL','YT','NT','NU']){await ev(`document.getElementById('journey-province').value='${code}';document.getElementById('journey-province').dispatchEvent(new Event('change'))`);assert.equal(await ev('LFSJourney.state().geo'),code);const msg=await ev("document.getElementById('journey-local').textContent");if(code==='PE')assert.match(msg,/one-stage/);if(['YT','NT','NU'].includes(code)){assert.match(msg,/eight interviews/);await ev('LFSJourney.seek(2)');assert.match(await ev("document.getElementById('journey-scene').textContent"),/TERRITORIAL/);}enhancementChecks.geographies.push(code);}
await ev("document.querySelector('#journey-map [data-geo=\"PE\"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}))");assert.equal(await ev('LFSJourney.state().geo'),'PE');
await ev("document.getElementById('journey-province').value='ON';document.getElementById('journey-province').dispatchEvent(new Event('change'))");
for(const [name,width,height,mobile]of[['desktop',1440,1000,false],['mobile',390,844,true]]){
await cdp('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await pause(100);
for(let stage=0;stage<7;stage++){await ev(`LFSJourney.seek(${stage})`);assert.equal(await ev('LFSJourney.state().stage'),stage);await ev("document.getElementById('journey-scene').scrollIntoView({behavior:'instant',block:'center'})");await pause(80);const layout=await ev("({width:innerWidth,documentWidth:document.documentElement.scrollWidth,sceneWidth:document.getElementById('journey-scene').getBoundingClientRect().width,svgTextOverflow:[...document.querySelectorAll('#journey-scene text')].filter(e=>e.getBBox().x+e.getBBox().width>document.getElementById('journey-scene').viewBox.baseVal.width+1).map(e=>e.textContent)})");assert(layout.documentWidth<=width+1,JSON.stringify(layout));enhancementChecks.layouts.push({name,stage,...layout});const shot=await cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});fs.writeFileSync(path.join(out,`${name}-journey-${stage+1}.png`),Buffer.from(shot.data,'base64'));}
await ev("LFSJourney.seek(0);document.getElementById('journey-map').scrollIntoView({behavior:'instant',block:'center'})");const shot=await cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});fs.writeFileSync(path.join(out,`${name}-canada-map.png`),Buffer.from(shot.data,'base64'));
}
await cdp('Emulation.setDeviceMetricsOverride',{width:1440,height:1000,deviceScaleFactor:1,mobile:false});
await ev("document.getElementById('donor-run').click()");await pause(1000);assert.match(await ev("document.getElementById('donor-field').textContent"),/35 \(imputed\)/);await ev("document.getElementById('donor-reset').click()");assert.match(await ev("document.getElementById('donor-field').textContent"),/missing/);
const repBefore=await ev("document.getElementById('replicate-result').textContent");await ev("document.getElementById('replicate-sim').elements.seed.value=339;document.getElementById('replicate-sim').requestSubmit()");assert.notEqual(await ev("document.getElementById('replicate-result').textContent"),repBefore);assert.equal(await ev("document.querySelectorAll('#replicate-table tbody tr').length"),10);
for(const mode of ['MCAR','MAR','MNAR']){await ev(`document.getElementById('imputation-sim').elements.mechanism.value='${mode}';document.getElementById('imputation-sim').requestSubmit()`);assert.match(await ev("document.getElementById('imputation-result').textContent"),/valid response trials/);}
await ev('LFSJourney.seek(0);LFSJourney.play()');await pause(350);await ev('LFSJourney.pause()');const held=await ev('LFSJourney.state().elapsed');await pause(300);assert.equal(await ev('LFSJourney.state().elapsed'),held);await ev('LFSJourney.play()');await pause(350);assert(await ev('LFSJourney.state().elapsed')>held);await ev('LFSJourney.pause()');enhancementChecks.pauseResume=true;
// A real-time complete 84-second playback, sampled every 12 seconds.
await ev("document.getElementById('journey-replay').click()");for(let i=0;i<7;i++){await pause(12100);const state=await ev('LFSJourney.state()');enhancementChecks.playback.push(state);console.log('Playback',JSON.stringify(state));}assert.equal(await ev('LFSJourney.state().elapsed'),84);assert.equal(await ev('LFSJourney.state().playing'),false);assert(await ev("!!document.getElementById('journey-uncertainty')"));enhancementChecks.fullPlayback=true;
await ev("document.getElementById('journey-prev').click()");assert.equal(await ev('LFSJourney.state().stage'),5);await ev("document.getElementById('journey-next').click()");assert.equal(await ev('LFSJourney.state().stage'),6);
await ev("document.getElementById('journey-stage').value=1;document.getElementById('journey-stage').dispatchEvent(new Event('change'))");assert.equal(await ev('LFSJourney.state().stage'),1);
await cdp('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});await ev('LFSJourney.play()');assert.equal(await ev('LFSJourney.state().playing'),false);assert.equal(await ev("document.getElementById('journey-play').disabled"),true);await ev('LFSJourney.seek(3)');assert.equal(await ev('LFSJourney.state().stage'),3);enhancementChecks.reducedMotion=true;
await cdp('Emulation.setEmulatedMedia',{features:[]});await ev("document.getElementById('journey-map-reset').click()");
'''
src=src.replace('const report={errors,failed,enhancementChecks,mathjaxRendered:',insert+'\nconst report={errors,failed,enhancementChecks,mathjaxRendered:')
src=src.replace("path.join(out,'browser-results.json')","path.join(out,'enhancement-browser-results.json')")
(base/'scripts/verify_enhancement_browser.js').write_text(src,encoding='utf-8')
